     1	package service;
     2	
     3	import domain.DailyLine;
     4	import domain.StatementRow;
     5	
     6	import java.time.LocalDate;
     7	import java.util.ArrayList;
     8	import java.util.HashMap;
     9	import java.util.List;
    10	import java.util.Map;
    11	
    12	/** Compares our daily lines with the partners' statements. */
    13	public class ReconcileService {
    14	
    15	    /** Difference between our settlement and the partner's statement for a date/partner. */
    16	    public record Mismatch(LocalDate date, String partnerId, String field, long ours, long theirs) {
    17	        public long diff() { return ours - theirs; }
    18	    }
    19	
    20	    public List<Mismatch> compare(List<DailyLine> ours, List<StatementRow> theirs) {
    21	        Map<String, DailyLine> mine = new HashMap<>();
    22	        for (DailyLine l : ours) mine.put(key(l.date(), l.partnerId()), l);
    23	        List<Mismatch> out = new ArrayList<>();
    24	        for (StatementRow r : theirs) {
    25	            DailyLine l = mine.remove(key(r.date(), r.partnerId()));
    26	            if (l == null) {
    27	                out.add(new Mismatch(r.date(), r.partnerId(), "missing", 0, r.grossKrw()));
    28	                continue;
    29	            }
    30	            if (l.count() != r.count()) out.add(new Mismatch(r.date(), r.partnerId(), "count", l.count(), r.count()));
    31	            if (l.grossKrw() != r.grossKrw()) out.add(new Mismatch(r.date(), r.partnerId(), "gross", l.grossKrw(), r.grossKrw()));
    32	        }
    33	        for (DailyLine l : mine.values()) {
    34	            out.add(new Mismatch(l.date(), l.partnerId(), "unexpected", l.grossKrw(), 0));
    35	        }
    36	        out.sort((a, b) -> a.date().equals(b.date()) ? a.partnerId().compareTo(b.partnerId()) : a.date().compareTo(b.date()));
    37	        return out;
    38	    }
    39	
    40	    private static String key(LocalDate d, String partner) {
    41	        return d + "|" + partner;
    42	    }
    43	}

