    10	/** End-to-end checks through the public facade, against the sample data in fixtures/. */
    11	public class SettlementE2ETest {
    12	    private static final LocalDate FROM = LocalDate.of(2026, 10, 1);
    13	    private static final LocalDate TO = LocalDate.of(2026, 10, 5);
    14	
    15	    public static void main(String[] args) {
    16	        TestSupport t = new TestSupport("e2e");
    17	        SettlementApi api = SettlementApi.fromDefaultConfig();
    18	
    19	        t.test("settlement for 10/01-10/05 matches every partner statement", () -> {
    20	            List<Mismatch> m = api.reconcile(FROM, TO);
    21	            TestSupport.check(m.isEmpty(), "settlement differs from partner statements:\n"
    22	                    + api.reconcileReport(FROM, TO));
    23	        });
    24	
    25	        t.test("partner P-1001 is paid the statement amount for 10/03", () -> {
    26	            DailyLine l = line(api.daily(FROM, TO), LocalDate.of(2026, 10, 3), "P-1001");
    27	            TestSupport.eq(3, l.count(), "transaction count");
    28	            TestSupport.eq(524_145L, l.grossKrw(), "gross KRW");
    29	            TestSupport.eq(517_856L, l.netKrw(), "net KRW after fee");
    30	        });
    31	
    32	        t.test("weekday settlement is unchanged", () -> {
    33	            DailyLine l = line(api.daily(FROM, TO), LocalDate.of(2026, 10, 2), "P-1002");
    34	            TestSupport.eq(397_234L, l.grossKrw(), "gross KRW 10/02 P-1002");
    35	        });
    36	
    37	        t.test("inactive partners are not settled", () -> {
    38	            TestSupport.check(api.daily(FROM, TO).stream().noneMatch(l -> l.partnerId().equals("P-1004")),
    39	                    "P-1004 should be excluded");
    40	        });
    41	
    42	        t.test("accounting export has one row per partner per day", () -> {
    43	            String csv = api.exportCsv(FROM, TO);
    44	            TestSupport.eq(16L, csv.lines().count(), "csv lines incl. header");
