/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    /** Vendor source that returns the settlement-basis rate for every date, including non-business days. */
    private static final int SETTLEMENT_SOURCE = 3;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private final Map<String, BigDecimal> settlementCache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Default-source quote, as published for display. Carried-forward values are returned as the vendor gave them. */
    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date. On a vendor non-business day the
     * default quote is the previous business day's rate, so the settlement-basis rate for that date is fetched instead.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.carriedForward()) return q.rate();
        String pair = CurrencyPairs.pairOf(currency);
        return settlementCache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date, SETTLEMENT_SOURCE)).rate();
        });
    }

